#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url" || true  # explorer.exe exits 1 even on success
    elif command -v cmd.exe     >/dev/null 2>&1; then cmd.exe /c start "" "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: o go-live da implementação geral (Etapas 1 a 5b). Rode no Git Bash, na raiz do repositório.
# Nenhum segredo é gravado em disco: os que faltarem vão direto para o Supabase por `supabase secrets set`.
# ──────────────────────────────────────────────────────────────────────────

PROJETO="ycbdilsmydvzezhlymty"
PAINEL="https://supabase.com/dashboard/project/$PROJETO"
FUNCOES=(account-discovery account-enrichment integration-connect integration-callback integration-tools
  reply-proposal-runner reply-proposal-send crm-handoff agent-conversation sequence-runner signal-runner
  unipile-account-status)

# segredo_no_supabase NOME VALOR: grava um segredo das Edge Functions sem passar o valor na linha de comando
# (vai num arquivo temporário só deste usuário, apagado logo depois).
segredo_no_supabase() {
  local nome="$1" valor="$2" arquivo
  arquivo=$(mktemp)
  chmod 600 "$arquivo"
  printf '%s=%s\n' "$nome" "$valor" > "$arquivo"
  if npx supabase secrets set --env-file "$arquivo" --project-ref "$PROJETO" >/dev/null 2>&1; then
    printf '  %s✓ gravado%s %s no Supabase\n' "$GREEN" "$RESET" "$nome"
  else
    SKIPPED+=("Segredo $nome: gravar por npx supabase secrets set --project-ref $PROJETO")
    warn "não consegui gravar $nome; fica na lista do final"
  fi
  rm -f "$arquivo"
}

TOTAL_STAGES=9

banner "Go-live da Althius"

stage "Código atualizado"
say "Tudo o que vai para o ar está na main do GitHub. Este passo traz a main para esta pasta."
if confirm "Rodar git checkout main e git pull origin main agora?"; then
  git checkout main && git pull origin main || warn "o git reclamou: resolva e rode o wizard de novo"
else
  SKIPPED+=("Atualizar a pasta: git checkout main && git pull origin main")
fi
pause "Tecle Enter para seguir"

stage "Publicar as Edge Functions"
say "Sobem as funções novas e as que mudaram: descoberta, enriquecimento, conexões, respostas sugeridas,"
say "Enviar ao CRM, Agentes, executor das Sequências, Sinais e o webhook da Unipile."
note "${FUNCOES[*]}"
note "O aviso 'Docker is not running' pode ser ignorado."
if confirm "Publicar as ${#FUNCOES[@]} funções agora?"; then
  npx supabase functions deploy "${FUNCOES[@]}" --project-ref "$PROJETO" \
    || { warn "alguma função falhou: copie a saída para o Claude"; SKIPPED+=("Deploy das Edge Functions"); }
else
  SKIPPED+=("Deploy: npx supabase functions deploy ${FUNCOES[*]} --project-ref $PROJETO")
fi
pause "Tecle Enter para seguir"

stage "Conferir os segredos"
say "A lista abaixo mostra só os NOMES dos segredos (e um resumo), nunca os valores."
npx supabase secrets list --project-ref "$PROJETO" 2>/dev/null | tee /tmp/althius-segredos.txt >/dev/null || true
for nome in APP_ORIGIN GROQ_API_KEY UNIPILE_API_KEY UNIPILE_WEBHOOK_SECRET APIFY_TOKEN; do
  if grep -q "$nome" /tmp/althius-segredos.txt 2>/dev/null; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$nome"
  else
    warn "$nome não aparece na lista"
  fi
done
if ! grep -q "APIFY_TOKEN" /tmp/althius-segredos.txt 2>/dev/null; then
  say "Sem o APIFY_TOKEN, a busca de contas pelo ICP, o enriquecimento e o comitê não rodam."
  open_url "https://console.apify.com/settings/integrations"
  step "Em Settings → API & Integrations, copie o Personal API token."
  ask_secret APIFY_TOKEN "Cole o token do Apify (Enter pula):"
  [[ -n "$APIFY_TOKEN" ]] && segredo_no_supabase APIFY_TOKEN "$APIFY_TOKEN" \
    || SKIPPED+=("APIFY_TOKEN no Supabase")
fi
rm -f /tmp/althius-segredos.txt
note "Se faltar outro segredo da lista, ele é de uma etapa anterior: me avise o nome."
pause "Tecle Enter para seguir"

stage "HubSpot pela chave de API (Private App)"
say "É o caminho que envia ao CRM hoje. A chave NÃO entra neste wizard: você cola na tela Conexões."
open_url "https://app.hubspot.com/"
step "No HubSpot: Configurações (engrenagem) → Integrações → Private Apps (pode aparecer como 'Apps legados')."
step "Crie um app 'Althius' com os escopos de leitura e escrita de Companies e Contacts (e o que o HubSpot pedir para Notes)."
note "Não confirmado daqui: o nome exato do menu e o escopo das notas. Se o menu for outro, me mande um print."
step "Copie o token do app (começa com pat-)."
step "Na Althius: Conexões → HubSpot → Habilitar (Administrador) → Usar chave de API → cole o token."
pause "Tecle Enter quando o cartão do HubSpot mostrar 'Conectado como …' (ou para pular)"

stage "HubSpot por autorização no app (opcional)"
say "Só se quiser o botão 'Conectar no HubSpot' (OAuth pelo MCP). Para Enviar ao CRM, a chave já basta."
if confirm "Configurar agora o MCP Auth App do HubSpot?"; then
  open_url "https://developers.hubspot.com/"
  step "Na conta de desenvolvedor: Development → MCP Auth Apps → criar o app."
  step "URL de retorno: https://$PROJETO.supabase.co/functions/v1/integration-callback"
  ask HUBSPOT_MCP_CLIENT_ID "Cole o Client ID:"
  ask_secret HUBSPOT_MCP_CLIENT_SECRET "Cole o Client secret:"
  [[ -n "$HUBSPOT_MCP_CLIENT_ID" ]] && segredo_no_supabase HUBSPOT_MCP_CLIENT_ID "$HUBSPOT_MCP_CLIENT_ID"
  [[ -n "$HUBSPOT_MCP_CLIENT_SECRET" ]] && segredo_no_supabase HUBSPOT_MCP_CLIENT_SECRET "$HUBSPOT_MCP_CLIENT_SECRET"
else
  note "Pulado. O cartão do HubSpot mostra 'Precisa configurar' nesse botão, e a chave de API segue funcionando."
fi
pause "Tecle Enter para seguir"

stage "Webhook da Unipile com respostas de WhatsApp e LinkedIn"
say "O webhook que já existe recebe os eventos de conta e de e-mail. Para as respostas de WhatsApp e"
say "LinkedIn pausarem a Sequência, ele precisa receber também o evento message.new."
warn "NÃO rode o scripts/wizard-unipile.sh de novo só para isso: ele cria um webhook novo com outro segredo."
open_url "https://dashboardv2.unipile.com/"
step "No painel da Unipile: Webhooks → abra o 'Althius account_status' → acrescente o evento message.new → salve."
note "Não confirmado daqui: se o painel permite editar os eventos. Se não permitir, me avise antes de mexer."
pause "Tecle Enter quando o message.new estiver no webhook (ou para pular)"

stage "Ligar WhatsApp e LinkedIn nas Sequências"
say "Os dois canais nascem desligados. Ligue só depois do passo anterior: sem o message.new, uma resposta"
say "não pausaria a Sequência. Antes, conecte o seu WhatsApp e o seu LinkedIn como Conta remetente."
open_url "$PAINEL/sql/new"
step "Cole no SQL Editor e clique em Run (tire a linha do canal que não quer ligar):"
printf "\n    select private.set_chat_channel_enabled('whatsapp', true);\n"
printf "    select private.set_chat_channel_enabled('linkedin', true);\n\n"
pause "Tecle Enter para seguir"

stage "Worker do Hermes (se você usa o Hermes)"
say "O worker ganhou as ferramentas dos Agentes. Pare o worker que está rodando (Ctrl+C) e ligue de novo:"
printf "\n    npx -y deno@2 run --node-modules-dir=none --allow-net --allow-env --allow-read --env-file=supabase/functions/_hermes-worker/.env supabase/functions/_hermes-worker/main.ts\n\n"
note "Para desligar as ferramentas sem mudar código: HERMES_FERRAMENTAS=off no .env do worker."
pause "Tecle Enter para seguir"

stage "Teste final"
say "Com o app aberto (npm run dev em projeto-althius-frontend), confira na ordem:"
step "Contas → Buscar contas pelo ICP: o custo aparece antes, e as candidatas caem na Caixa de Descobertas."
step "Aceite uma candidata: ela vira Conta-alvo; peça o comitê de compra e aceite um Contato."
step "Conexões → HubSpot conectado. Na Conta-alvo: Enviar ao CRM → a empresa aparece no HubSpot e o cartão vai para No CRM."
step "Agentes: 'Scopus, ache contas do nosso ICP' → o passo leva à Caixa de Descobertas."
step "Sequência de E-mail: responda o e-mail de teste → em até 2 minutos aparece a Resposta sugerida."
step "WhatsApp ou LinkedIn (se ligou): um passo sai, e a sua resposta pausa a Sequência."
note "Anote o que falhar (print + o que você fez) e mande para o Claude."
pause "Tecle Enter para terminar"

finish
